# Final submission: Pattern 1 - Start at CENTER (7,7) with INPUT SPACING (3)

grid = [[0]*15 for _ in range(15)]
r, c = 7, 7
spacing = 3
while r < 15 and c < 15:
    grid[r][c] = 2
    r += spacing
    c += spacing

print("Final attempt:")
for r in range(15):
    for c in range(15):
        if grid[r][c] == 2:
            print(f"({r}, {c})")
